class Objects(CommonPage):
    """
    The class corresponding to 'Objects' page on selenium_coam web, all operations under 'Objects'
    page will be implemented or added in its corresponding classes.
    """
    _instance_dict = {}

    def __init__(self, driver):
        if not self._instance_dict:
            self._instance_dict = {
                "Network View": NetworkViewPage(driver)
            }
        super(Objects, self).__init__(driver, self._instance_dict)


