    def alarm_upload(self, dn_name):
        # self._driver.switch_to_frame("network-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("network-view"))
        self._select_use_case_on_objects_page("Network element health")
        self._input_filter(dn_name)
        time.sleep(5)
        # self.click_enabled_element((By.XPATH, self._SELECT_DROP_DOWN_XPATH))
        # self.click_enabled_element((By.XPATH, self._NETWORK_ELEMENT_HEALTH_XPATH))
        self.perform_element_hover_by_xpath(self._OBJECTS_BODY_XPATH.format(dn_name))
        try:
            self.click_enabled_element((By.XPATH, self._ALARM_UPLOAD_XPATH.format(dn_name)))
        except Exception as e:
            self.click_enabled_element((By.XPATH, self._ALARM_UPLOAD_XPATH_1.format(dn_name)))
        alarm_upload_modal = AlarmUploadModal(driver=self._driver)
        alarm_upload_modal.wait_until_alarm_upload_modal_appear()
        alarm_upload_modal.confirm_alarm_upload()
        self._driver.switch_to_default_content()

    def _clear_filter(self):
        if self.element_exists((By.XPATH, self._FILTER_CLOSE_XPATH)):
            elements = self._driver.find_elements_by_xpath(self._FILTER_CLOSE_XPATH)
            for element in elements:
                element.click()

        if self.element_exists((By.XPATH, '//div[@class="chips-close-icon"]')):
            elements = self._driver.find_elements_by_xpath('//div[@class="chips-close-icon"]')
            for element in elements:
                element.click()

        if self.element_exists((By.XPATH, self._MORE_XPATH)):
            self._driver.find_element_by_xpath(self._MORE_XPATH).click()
            time.sleep(3)
            li_xpath = '//li[contains(text(),"Remove chip")]'
            self._driver.find_element_by_xpath(li_xpath).click()

        if self.element_exists((By.XPATH, '//div[@data-test="flex-search-chip-content-area"]')):
            elements = self._driver.find_elements_by_xpath('//div[@data-test="flex-search-chip-content-area"]')
            self.clear_text_of_enabled_element((By.XPATH, self._FILTER_FIELD_XPATH))
            for i in range(len(elements)):
                self.clear_text_of_enabled_element((By.XPATH, self._FILTER_FIELD_XPATH))
                self.clear_text_of_enabled_element((By.XPATH, self._FILTER_FIELD_XPATH))

    def _input_filter(self, dn_name, filter_name="NE identifier", **kwargs):
        self._clear_filter()
        self.element_exists(locator=(By.XPATH, self._OBJECTS_PAGE_LOAD_FINISH_XPATH), timeout=5)
        filter_elements = self._driver.find_elements_by_xpath('//div[@data-test="flex-search-right-section"]')
        filter_name_list = [filter_name]
        filter_list = [dn_name]
        if len(filter_elements) > 1:
            logging.info('Note that there are two filter input boxes here!')
            if kwargs.get('filter_name_2'):
                filter_name_list.append(kwargs.get('filter_name_2'))
                filter_list.append(kwargs.get('filter_2'))
        for i in range(len(filter_name_list)):
            filter_element = filter_elements[i]
            if i > 0:
                filter_elements = self._driver.find_elements_by_xpath('//div[@data-test="flex-search-right-section"]')
                filter_element = filter_elements[i]
                self._driver.execute_script("arguments[0].click();", filter_element)
            else:
                filter_element.click()
            time.sleep(3)
            input_elements = self._driver.find_elements_by_xpath(self._FILTER_FIELD_XPATH)
            self.input_text_to_field_by_element(input_elements[0], filter_name_list[i])
            input_elements = self._driver.find_elements_by_xpath(self._FILTER_FIELD_XPATH)
            self.input_text_to_field_by_element(input_elements[1], "=")
            input_elements = self._driver.find_elements_by_xpath(self._FILTER_FIELD_XPATH)
            self.input_text_to_field_by_element(input_elements[2], filter_list[i])
            if len(filter_name_list) > 1:
                input_elements[2].send_keys(Keys.ENTER)
            time.sleep(3)
            # for click next filter,it is necessary
            if len(filter_name_list) > 1:
                self._driver.find_element_by_xpath(self._FILTER_INPUT_XPATH).click()
            time.sleep(1)

    def _input_filters_on_parameters_view(self, **kwargs):
        filter_condition = {}
        for key, value in kwargs.items():
            if key not in self._ALL_FILTER_CONDITIONS_ON_PARAMETERS_VIEW:
                raise Exception("Got an unexpected filter condition-{}, "
                                "the condition should be in {}".
                                format(key, ', '.join(self._ALL_FILTER_CONDITIONS_ON_PARAMETERS_VIEW)))
            # key = key.replace('_', ' ').capitalize()
            # if key == "actual_ui_value":
            #     key = key.replace('Actual ui value', 'Actual UI value')
            filter_condition[key] = value
        self._clear_filter()
        for key, value in filter_condition.items():
            self.insert_text_to_enable_element(locator=(By.XPATH, self._FILTER_FIRST_FIELD_XPATH),
                                               text=key)
            self.insert_text_to_enable_element(locator=(By.XPATH, self._FILTER_CONDITION_INPUT_XPATH),
                                               text="=")
            self.wait_for_visibility(locator=(By.XPATH, self._FILTER_CONDITION_SELECT_XPATH))
            self.click_element_by_xpath(self._FILTER_CONDITION_SELECT_XPATH)
            self.insert_text_to_enable_element(locator=(By.XPATH, self._FILTER_QUERY_INPUT_XPATH),
                                               text=value)
            self.wait_for_visibility(locator=(By.XPATH, self._FILTER_QUERY_SELECT_XPATH.format(value)))
            self.click_element_by_xpath(self._FILTER_QUERY_SELECT_XPATH.format(value))
        self.wait_for_visibility(locator=(By.XPATH, self._PARAMETERS_BODY_XPATH))

    def _select_use_case_on_objects_page(self, option_text):
        self.click_enabled_element((By.XPATH, self._USE_CASE_ELEMENT_ON_OBJECT_PAGE))
        if option_text == "Network element health":
            use_case_xpath = self._DROP_DOWN_OPTION_OF_NETWORK_ELEMENT_HEALTH
        if option_text == "MRBTS state management":
            use_case_xpath = self._DROP_DOWN_OPTION_OF_MRBTS_CELL_STATE_MANAGEMENT
        if option_text == "SW management":
            use_case_xpath = self._DROP_DOWN_OPTION_OF_SW_MANAGEMENT
        if option_text == "NE user account management":
            use_case_xpath = self._DROP_DOWN_OPTION_OF_NE_USER_ACCOUNT_MANAGEMENT
        if option_text == "5G MRBTS logical cell view":
            use_case_xpath = '//*[@id="PROVIDED-5G_MRBTS_logical_cell_view-0"]'
        if option_text == "Network element health":
            use_case_xpath = '//*[@id="PROVIDED-Network_element_health-0"]'
        if option_text == "Consistency reports":
            use_case_xpath = '//*[@id="PROVIDED-Consistency_reports-0"]'
        self.click_element_by_xpath(use_case_xpath)
        self.element_exists(locator=(By.XPATH, self._OBJECTS_PAGE_LOAD_FINISH_XPATH), timeout=5)

    def _select_use_case_on_storage_page(self, option_text):
        self.click_element_by_xpath(self._USE_CASE_ELEMENT_ON_STORAGE_PAGE)
        if option_text == "Plans":
            use_case_xpath = self._DROP_DOWN_OPTION_OF_PLANS
        self.click_element_by_xpath(use_case_xpath)
        self.element_exists(locator=(By.XPATH, self._STORAGE_PAGE_LOAD_FINISH_XPATH), timeout=10)

    def _select_use_case_on_parameters_page(self, option_text):
        self.click_element_by_xpath(self._USE_CASE_ELEMENT_ON_PARAMETERS_PAGE)
        if option_text == "Parameter editing":
            use_case_xpath = self._DROP_DOWN_OPTION_OF_PARAMETER_EDITING
        self.click_element_by_xpath(use_case_xpath)
        self.element_exists(locator=(By.XPATH, self._PARAMETERS_PAGE_LOAD_FINISH_XPATH), timeout=10)

    def configuration_upload(self, dn_name, single_workflow, daily):
        #self._driver.switch_to_frame("network-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("network-view"))
        self._select_use_case_on_objects_page("Network element health")
        self._input_filter(dn_name)
        time.sleep(5)
        if self.element_exists(locator=(By.XPATH, self._CONFIGURATION_UPLOAD_BUTTON.format(dn_name)), timeout=5):
            self.click_element_by_xpath(self._CONFIGURATION_UPLOAD_BUTTON.format(dn_name))
        elif self.element_exists(locator=(By.XPATH, self._CONFIGURATION_MORE_ACTIONS.format(dn_name)), timeout=5):
            self.click_element_by_xpath(self._CONFIGURATION_MORE_ACTIONS.format(dn_name))
            self.click_element_by_xpath(self._CONFIGURATION_UPLOAD_IN_MORE_ACTIONS)

        if self.element_exists(locator=(By.XPATH, self._CONFIRM_UPLOAD), timeout=5):
            self.click_element_by_xpath(self._CONFIRM_UPLOAD)

        self._driver.switch_to_default_content()
        # self._driver.switch_to_frame("workflow_configuration-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("workflow_configuration-view"))
        self.wait_for_enable(locator=(By.XPATH, self._SETTINGS_PANEL), timeout=30)
        if not single_workflow:
            self.click_element_by_xpath(self._RECURRENT_WORKFLOWS)
        if not single_workflow and not daily:
            self.click_element_by_xpath(self._SCHEDULE_FORMULA_WEEKLY)
        self.click_element_by_xpath(self._RUN_BUTTON)
        self._driver.switch_to_default_content()

    def import_plan(self, dn_name, path_of_plan_file, plan_name=None):
        # self._driver.switch_to_frame("network-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("network-view"))
        self._select_use_case_on_objects_page("Network element health")
        self._input_filter(dn_name)
        time.sleep(5)
        self.click_element_by_xpath(self._SHOW_DETAIL)
        self._driver.switch_to_default_content()
        self.click_element_by_xpath(self._STORAGE_BUTTON)
        self.wait_for_visibility_by_xpath(self._STORAGE_PAGE_LOAD_FINISH_XPATH, 60)
        # self._driver.switch_to_frame("plan-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("plan-view"))
        self.wait_for_visibility_by_xpath(self._USE_CASE_ELEMENT_ON_STORAGE_PAGE, 30)
        self._select_use_case_on_storage_page("Plans")

        self.click_element_by_xpath(self._OPEN_FILE_IMPORT_WINDOW)
        time.sleep(2)
        # self.click_element_by_xpath('//span[@class="fileSelectLink"]')
        ele = self._driver.find_element_by_xpath(self._PLAN_FILE_PATH_INPUT_FIELD)
        ele.send_keys(path_of_plan_file)
        time.sleep(2)
        if plan_name:
            plan_name_field = self._driver.find_element_by_xpath(self._PLAN_NAME_INPUT_FIELD)
            self.input_text_to_field_by_element(plan_name_field, plan_name)
            time.sleep(3)
        self.click_element_by_xpath(self._IMPORT_BUTTON)
        self._driver.switch_to_default_content()
        self.click_element_by_xpath(self._STORAGE_TOOLBAR)
        self.wait_for_visibility(locator=(By.XPATH, self._STORAGE_PAGE_LOAD_FINISH_XPATH))

    def get_parameters_value(self, dn_name, parameter_names_list):
        # self._driver.switch_to_frame("network-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("network-view"))
        self._select_use_case_on_objects_page("Network element health")
        self._input_filter(dn_name)
        time.sleep(5)
        self.click_element_by_xpath(self._CHECKBOX_FOR_DN.format(dn_name.split("/")[-1]))
        self.click_element_by_xpath(self._SHOW_DETAIL)
        self._driver.switch_to_default_content()
        self.click_element_by_xpath(self._PARAMETERS_BUTTON)
        self.wait_for_visibility_by_xpath(self._PARAMETERS_PAGE_LOAD_FINISH_XPATH, 60)
        time.sleep(10)
        # self._driver.switch_to_frame("parameter-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("parameter-view"))

        self._select_use_case_on_parameters_page("Parameter editing")
        self.wait_for_visibility_by_xpath(self._USE_CASE_ELEMENT_ON_PARAMETERS_PAGE, 30)
        self.click_element_by_xpath(self._MANAGE_COLUMNS_BUTTON)
        self.click_element_by_xpath(self._RESET_ALL_COLUMNS)
        self.click_element_by_xpath(self._SHOW_ALL_PARAMETERS_NAMES)
        para_info_list = []
        for para_name in parameter_names_list:
            self._input_filters_on_parameters_view(parameter=para_name)
            row_objects = self._driver.find_elements_by_xpath(self._PARAMETER_ROW_NUM)
            row_num = len(row_objects)
            for row_index in range(0, row_num):
                para_info_dict = {}
                for key in self._PARAMETER_COL_ID:
                    cid = self._PARAMETER_COL_ID[key]
                    xpath = self._PARAMETER_COL_XPATH.format(row_index, cid)
                    if len(self.get_attribute_by_xpath(xpath, "title")) > 0:
                        para_info_dict[key] = self.get_attribute_by_xpath(xpath, "title")
                    else:
                        para_info_dict[key] = self.get_text_by_xpath(xpath)
                para_info_list.append(para_info_dict)
        self._driver.switch_to_default_content()
        return para_info_list

    def export_actual_configuration(self, dn_name, path_of_download_file):
        # self._driver.switch_to_frame("network-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("network-view"))

        self._select_use_case_on_objects_page("Network element health")
        self._input_filter(dn_name)
        time.sleep(5)
        if self.element_exists(locator=(By.XPATH, self._EXPORT_ACTUAL_CONFIGURATION_BUTTON.format(dn_name)), timeout=5):
            self.click_element_by_xpath(self._EXPORT_ACTUAL_CONFIGURATION_BUTTON.format(dn_name))
        self._driver.switch_to_default_content()
        file_path = path_of_download_file + "/actual.xml"
        time.sleep(5)
        return file_path

    def reset_element(self, dn_name):
        # self._driver.switch_to_frame("network-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("network-view"))
        self._select_use_case_on_objects_page("MRBTS state management")
        self._input_filter(dn_name)
        time.sleep(5)

        self.click_enabled_element((By.XPATH, self._CHECKBOX_FOR_DN.format(dn_name.split("/")[-1])))
