    def sw_import(self, path_of_sw_version):
        # self._driver.switch_to_frame("network-view")
        self._driver.switch_to.frame(self._driver.find_element_by_name("network-view"))
        self._select_use_case_on_objects_page("SW management")
        self.click_element_by_xpath(self._USE_CASE_SPECIFIC_WORKFLOW)
        self.click_element_by_xpath(self._SWM_OPERATION["import"])
        ele = self._driver.find_element_by_xpath(self._PLAN_FILE_PATH_INPUT_FIELD)
        ele.send_keys(path_of_sw_version)
        self.click_element_by_xpath(self._NE_TYPE_ELEMENT)
        time.sleep(1)
        if "FHGW" in path_of_sw_version:
            self.perform_element_hover_by_xpath(self._NE_TYPE_OPTION.format("FHGW"))
            self.click_element_by_xpath(self._NE_TYPE_OPTION.format("FHGW"))
