    def _open_the_operation_expand(self):
        """ open the operation expand when operation is closed """
        element_xpath = '//*[@id="expansionPanel"]/div[3]/div/div[1]/div[2]'
        operation_expand_element = self._driver.find_element_by_xpath(element_xpath)
        class_name = operation_expand_element.get_attribute('class')
        if class_name.find('expanded') < 0:
            logging.info('need to expand')
            operation_expand_element.send_keys(Keys.ENTER)

    def sw_download_activation(self, dn_name, sw_version=None, operation_type="download"):
        self._driver.maximize_window()
        time.sleep(3)
        self._driver.switch_to.frame(self._driver.find_element_by_name("network-view"))
        self._driver.implicitly_wait(5)
        self._select_use_case_on_objects_page("SW management")
        self._input_filter(dn_name)
        time.sleep(10)
        self.click_element_by_xpath(self._SWM_CHECKBOX_FOR_DN.format(dn_name))
        self.click_element_by_xpath(self._USE_CASE_SPECIFIC_WORKFLOW)
        self.click_element_by_xpath(self._SW_OPERATION_XPATH)
        self._driver.switch_to_default_content()
        time.sleep(10)
        self._driver.switch_to.frame(self._driver.find_element_by_name("workflow_configuration-view"))
        self._open_the_operation_expand()
        time.sleep(3)
        _operation_type_list = operation_type.split('_AND_')
        for _operation_type in _operation_type_list:
            element = self._driver.find_element_by_xpath(self._UPGRADE_MODE[_operation_type])
            element.send_keys(Keys.ENTER)
        if operation_type.upper() in ('DOWNLOAD', 'ACTIVATION', 'DOWNLOAD_AND_ACTIVATION', 'PROVISION'):
            if sw_version is None:
                raise Exception("need sw version when dn_name in ['download', 'activation', "
                                "'download_and_activation', 'provision']")
            self._select_software_package(sw_version)
        time.sleep(3)
        self.click_element_by_xpath(self._RUN_BUTTON)
        self._driver.switch_to_default_content()

    def _select_software_package(self, sw_version):
        self.insert_text_to_enable_element(locator=(By.XPATH, '//input[@id="react-select-select-sw-package"]'),
                                           text=sw_version)
        self.perform_element_hover_by_xpath(self._SW_VERSION_OPTION.format(sw_version))
        self.click_element_by_xpath(self._SW_VERSION_OPTION.format(sw_version))

