    def _confirm_lock_unlock_operation(self, operation):
        if operation.lower() == 'lock':
            lock_cells_modal = LockCellsModal(driver=self._driver)
            lock_cells_modal.wait_until_lock_cells_modal_appear()
            lock_cells_modal.confirm_lock_cells()
            # lock_cells_modal.cancel_lock_cells()
        if operation.lower() == 'unlock':
            unlock_cells_modal = UNLockCellsModal(driver=self._driver)
            unlock_cells_modal.wait_until_unlock_cells_modal_appear()
            unlock_cells_modal.confirm_unlock_cells()
            # unlock_cells_modal.cancel_unlock_cells()

