    def launch_element_manager(self, object_identifier, is_need_login=True, login_username="Nemuadmin",
                               login_password="nemuuser"):
        self._driver.switch_to.frame(self._driver.find_element_by_name("network-view"))
        self._select_use_case_on_objects_page("5G MRBTS logical cell view")
        self._clear_for_launch_element_manager()
        self._input_filter(object_identifier)
        self.click_enabled_element((By.XPATH, self._CHECKBOX_FOR_DN.format(object_identifier)))
        launch_element_button = '//button[@aria-label="launch element manager"]'
        self.click_enabled_element((By.XPATH, launch_element_button))

        start_time = end_time = time.time()
        while end_time - start_time < 30:
            windows = self._driver.window_handles
            if len(windows) > 1:
                break
            else:
                time.sleep(2)
                end_time = time.time()
        if is_need_login is True:
            self._driver.switch_to.window(windows[-1])
            if object_identifier.startswith('MRBTS'):
                self._login_after_launch_element_manager_with_MRBTS(username=login_username, password=login_password)
                time.sleep(10)
            elif object_identifier.startswith('ASI'):
                self._login_after_launch_element_manager_with_ASI(username=login_username, password=login_password)
                time.sleep(10)
            else:
                raise Exception('object_identifier %s not support, must be MRBTS or ASI' % object_identifier)
            self._driver.switch_to.window(windows[0])
        self._driver.switch_to_default_content()

    def _clear_for_launch_element_manager(self):
        if self.element_exists((By.XPATH, self._FILTER_CLOSE_XPATH)):
            while True:
                elements = self._driver.find_elements_by_xpath(self._FILTER_CLOSE_XPATH)
                if elements:
                    elements[0].click()
                    self._driver.find_element_by_xpath(self._FILTER_INPUT_XPATH).click()
                else:
                    break
        filter_elements = self._driver.find_elements_by_xpath('//div[@data-test="flex-search-right-section"]')
        filter_elements[0].click()

    def _login_after_launch_element_manager_with_MRBTS(self, username, password):
        username_path = '//input[@id="login-username"]'
        password_path = '//input[@id="login-password"]'
        login_button_path = '//button[contains(@class, "p-ripple p-element p-button p-component")]'
        self.insert_text_to_enable_element(locator=(By.XPATH, username_path),
                                           text=username)
        self.insert_text_to_enable_element(locator=(By.XPATH, password_path),
                                           text=password)
        self.click_enabled_element((By.XPATH, login_button_path))

    def _login_after_launch_element_manager_with_ASI(self, username, password):
        username_path = '//input[@id="mat-input-0"]'
        password_path = '//input[@id="mat-input-1"]'
        login_button_path = '//button[@class="ot-button-primary"]'
        self.insert_text_to_enable_element(locator=(By.XPATH, username_path),
                                           text=username)
        self.insert_text_to_enable_element(locator=(By.XPATH, password_path),
                                           text=password)
        self.click_enabled_element((By.XPATH, login_button_path))
        accept_path = '//button[contains(@class, "ot-button-primary ng-star-inserted")]'
        self.click_enabled_element((By.XPATH, accept_path))

    def _input_filter_for_multi_NE(self, condition=':', **kwargs):
        filter_condition = {}
        for key, value in kwargs.items():
            if key not in self.ALL_FILTER_CONDITIONS:
                raise Exception("Got an unexpected filter condition-{}, "
                                "the condition should be in {}".format(key, ', '.join(self.ALL_FILTER_CONDITIONS)))
            key = key.replace('_', ' ')
            filter_condition[key] = value
        self._clear_filter()
        filter_elements = self._driver.find_elements_by_xpath('//div[@data-test="flex-search-right-section"]')
        filter_elements[0].click()
        for key, value in filter_condition.items():
            value = [value]
            input_elements = self._driver.find_elements_by_xpath(self._FILTER_FIELD_XPATH)
            self.input_text_to_field_by_element(input_elements[0], key)

            input_elements = self._driver.find_elements_by_xpath(self._FILTER_FIELD_XPATH)
            self.input_text_to_field_by_element(input_elements[-1], condition)

            for text in value:
                input_elements = self._driver.find_elements_by_xpath(self._FILTER_FIELD_XPATH)
                self.input_text_to_field_by_element(input_elements[-1], text)
        filter_elements[0].send_keys(Keys.ENTER)
        time.sleep(3)

    def check_against_rules(self, object_id_list, name, validation_rules='CU DU consistency'):
        # self._driver.maximize_window()
        self._driver.set_window_size(width=1296, height=696)
        self._driver.implicitly_wait(10)
        self._driver.switch_to.frame(self._driver.find_element_by_name("network-view"))
        self._driver.implicitly_wait(3)
        self._select_use_case_on_objects_page("Network element health")
        self._input_filter_for_multi_NE(condition='in', NE_identifier=object_id_list)

        time.sleep(10)
        for object_id in object_id_list:
            self.click_element_by_xpath(self._SWM_CHECKBOX_FOR_DN.format(object_id))
            time.sleep(0.1)
        self.click_element_by_xpath(self._USE_CASE_SPECIFIC_WORKFLOW)
        check_rule_against_path = '//li[@id="actualCmRules"]'
        self.click_element_by_xpath(check_rule_against_path)
        self._driver.switch_to_default_content()

        self._driver.implicitly_wait(10)
        self._driver.switch_to.frame(self._driver.find_element_by_name("workflow_configuration-view"))
        name_path = '//input[@id="name-textInput"]'
        plan_name_field = self._driver.find_element_by_xpath(name_path)
        self.input_text_to_field_by_element(plan_name_field, name)

        filter_path = '//input[@id="filter-input-text-input-textInput"]'
        self.input_text_to_field_by_element(self._driver.find_element_by_xpath(filter_path), validation_rules)

        time.sleep(3)
        consistency_button_path = '//*[@id="{}-toggleInput"]/div[1]'.format(validation_rules)
        self.wait_for_visibility(locator=(By.XPATH, consistency_button_path))
        self.click_element_by_xpath(consistency_button_path)
        self.click_element_by_xpath(self._RUN_BUTTON)
        self._driver.implicitly_wait(3)
        self.click_element_by_xpath(self._CLOSE_BUTTON)
        self._driver.switch_to_default_content()



